/* Demo mode for the hosted dashboard at /llmprof/try/.
 *
 * The dashboard is the real app.js, unmodified. There is no proxy behind it
 * here, so this shim answers its five read endpoints from a static snapshot
 * (demo-data.json, generated by scripts/demo/gen_demo_data.py from llmprof's own
 * ingest + pricing, so every number is what a real run would show). It is loaded
 * before app.js, installs a fetch interceptor, and adds a "this is a recorded
 * demo" banner. Anything it does not recognize falls through to the network.
 */
(function () {
  "use strict";
  window.__LLMPROF_DEMO = true;

  var realFetch = window.fetch.bind(window);
  // Kick off the snapshot load immediately (before app.js fires its first
  // fetch). Every intercepted call awaits this, so order does not matter.
  var DATA = realFetch("./demo-data.json").then(function (r) { return r.json(); });

  function resp(body, ok, status) {
    return {
      ok: ok !== false,
      status: status || 200,
      headers: { get: function () { return null; } },
      json: function () { return Promise.resolve(body); },
      text: function () { return Promise.resolve(JSON.stringify(body)); },
    };
  }

  function route(pathname, data) {
    // /llmprof/api/<thing>[/<id>]
    var m = pathname.match(/\/llmprof\/api\/(summary|traces|sessions)(?:\/([^/]+))?$/);
    if (!m) return undefined;
    var kind = m[1], id = m[2];
    if (kind === "summary") return resp(data.summary);
    if (kind === "traces") {
      if (id == null) return resp(data.traces);
      var t = data.trace[String(id)];
      return t ? resp(t) : resp({ detail: "trace not found" }, false, 404);
    }
    if (kind === "sessions") {
      if (id == null) return resp(data.sessions);
      var s = data.session[String(id)];
      return s ? resp(s) : resp({ detail: "session not found" }, false, 404);
    }
    return undefined;
  }

  window.fetch = function (input, init) {
    var url = typeof input === "string" ? input : (input && input.url) || "";
    var path;
    try { path = new URL(url, window.location.href).pathname; }
    catch (e) { return realFetch(input, init); }
    if (path.indexOf("/llmprof/api/") === -1) return realFetch(input, init);
    return DATA.then(function (data) {
      var r = route(path, data);
      return r || realFetch(input, init);
    });
  };

  // A slim, honest banner. The dashboard otherwise looks and behaves exactly as
  // it does locally. Subtract the banner height from .app so nothing is clipped
  // (body is overflow:hidden and .app is calc(100vh - 56px)).
  var BANNER_H = 34;
  function mount() {
    if (document.getElementById("llmprof-demo-banner")) return;
    var style = document.createElement("style");
    style.textContent =
      "#llmprof-demo-banner{height:" + BANNER_H + "px;display:flex;align-items:center;" +
      "justify-content:center;gap:10px;font:12px/1 var(--mono,monospace);" +
      "color:#cdd3df;background:linear-gradient(180deg,#1a1d27,#12141b);" +
      "border-bottom:1px solid #232734;padding:0 14px;white-space:nowrap;overflow:hidden}" +
      "#llmprof-demo-banner b{color:#3ddc97;font-weight:600}" +
      "#llmprof-demo-banner a{color:#7c84ff;text-decoration:none;border-bottom:1px solid transparent}" +
      "#llmprof-demo-banner a:hover{border-bottom-color:#7c84ff}" +
      ".app{height:calc(100vh - 56px - " + BANNER_H + "px) !important}";
    document.head.appendChild(style);

    var bar = document.createElement("div");
    bar.id = "llmprof-demo-banner";
    bar.innerHTML =
      '<span><b>Live demo</b> &middot; a recorded session, read-only. ' +
      'Run <code>pipx install llmprof &amp;&amp; llmprof up</code> to profile your own.</span>' +
      '<a href="https://luthrag.github.io/llmprof/start/installation/">Install &rarr;</a>' +
      '<a href="https://github.com/luthraG/llmprof">GitHub</a>';
    document.body.insertBefore(bar, document.body.firstChild);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", mount);
  } else {
    mount();
  }
})();
